#[derive(Clone, Copy)]
#[repr(u8)]
enum Color {
    Black = 0x0, Blue = 0x1, Green = 0x2, Cyan = 0x3,
    Red = 0x4, Magenta = 0x5, Brown = 0x6, Gray = 0x7,
    DarkGray = 0x8, BrightBlue = 0x9, BrightGreen = 0xA, BrightCyan = 0xB,
    BrightRed = 0xC, BrightMagenta = 0xD, Yellow = 0xE, White = 0xF,
}

struct Cursor {
    position: usize,
    foreground: Color,
    background: Color,
}

impl Cursor {
    fn color(&self) -> u8 {
        (self.foreground as u8) | ((self.background as u8) << 4)
    }

    fn print(&mut self, framebuffer: *mut u8, text: &[u8]) {
        let color = self.color();
        for &ch in text {
            unsafe {
                framebuffer.add(self.position).write_volatile(ch);
                framebuffer.add(self.position + 1).write_volatile(color);
            }
            self.position += 2;
        }
    }
}

fn main() {
    let mut memory = [0u8; 80 * 25 * 2]; // stands in for the 4,000 bytes at 0xb8000
    let mut cursor = Cursor { position: 0, foreground: Color::BrightCyan, background: Color::Black };
    cursor.print(memory.as_mut_ptr(), b"Rust in Action");
    println!("{:02x?}", &memory[..8]);
    let text: String = memory[..28].chunks(2).map(|cell| cell[0] as char).collect();
    println!("{text}");
}

use core::fmt::{self, Write};

struct Fixed<const N: usize> {
    buf: [u8; N],
    len: usize,
}

impl<const N: usize> Write for Fixed<N> {
    fn write_str(&mut self, s: &str) -> fmt::Result {
        let bytes = s.as_bytes();
        if self.len + bytes.len() > N {
            return Err(fmt::Error);
        }
        self.buf[self.len..self.len + bytes.len()].copy_from_slice(bytes);
        self.len += bytes.len();
        Ok(())
    }
}

fn main() {
    let mut w = Fixed::<32> { buf: [0; 32], len: 0 };
    write!(w, "panicked at {}:{}", "main.rs", 42).unwrap();
    println!("{}", core::str::from_utf8(&w.buf[..w.len]).unwrap());

    let mut tiny = Fixed::<4> { buf: [0; 4], len: 0 };
    println!("{:?}", write!(tiny, "{}", 123456));
}

use std::marker::PhantomData;

struct Input;
struct Output;

struct Pin<Mode> {
    number: u8,
    _mode: PhantomData<Mode>,
}

impl Pin<Input> {
    fn new(number: u8) -> Self {
        Pin { number, _mode: PhantomData }
    }
    fn into_output(self) -> Pin<Output> {
        println!("pin {} configured as output", self.number);
        Pin { number: self.number, _mode: PhantomData }
    }
}

impl Pin<Output> {
    fn set_high(&mut self) {
        println!("pin {} high", self.number);
    }
}

fn main() {
    let button = Pin::new(14);
    let mut led = Pin::new(21).into_output();
    led.set_high();
    // button.set_high(); // error: no method `set_high` for `Pin<Input>`
    let _ = button;
    println!("size of a pin: {} byte", size_of::<Pin<Output>>());
}

const W: usize = 12;
const H: usize = 3;

struct Screen {
    cells: [u16; W * H],
    row: usize,
    col: usize,
    attr: u8,
}

impl Screen {
    fn write_byte(&mut self, b: u8) {
        // TODO: handle b'\n', and wrap when self.col == W
        self.cells[self.row * W + self.col] = (self.attr as u16) << 8 | b as u16;
        self.col += 1;
    }

    fn show(&self) {
        for r in 0..H {
            let line: String = self.cells[r * W..(r + 1) * W]
                .iter()
                .map(|&c| match (c & 0xff) as u8 {
                    0 => '.',
                    b if b < 0x20 => '?',
                    b => b as char,
                })
                .collect();
            println!("|{line}|");
        }
    }
}

fn main() {
    let mut s = Screen { cells: [0; W * H], row: 0, col: 0, attr: 0x0b };
    for &b in b"hello\nkernel world" {
        s.write_byte(b);
    }
    s.show();
    println!("attribute {:#04x}", s.cells[0] >> 8);
}
